INSERT INTO `rulings` (`uuid`, `text`, `id`, `date`) VALUES ('61d228aa-2646-5398-8bfa-77f0150b8aa2', 'Circle of Flame’s ability triggers only if a creature without flying is declared as an attacker during the declare attackers step. If a creature with flying attacks you or a planeswalker you control and then loses flying, or if a creature without flying i', 50096, '2014-07-18');
INSERT INTO (`id`, `translation`, `setCode`, `language`) VALUES (927, '차원의 혼돈', 'PLC', 'Korean'), (125, 'Rinascita di Alara', 'ARB', 'Italian'), (538, 'Darksteel', 'DST', 'Portuguese (Brazil)'), (62, '核心系列第八版', '8ED', 'Chinese Traditional'), (391, 'Ajani vs. Nicol Bolas', 'DDH', 'Chinese Simplified');
INSERT INTO `MagicRulings` (`uuid`, `id`, `text`, `date`) VALUES ('834f3765-b24f-59c1-9309-f0bcc131255f', 53348, 'Unlike other Aura spells, an Aura spell with bestow isn’t countered if its target is illegal as it begins to resolve. Rather, the effect making it an Aura spell ends, it loses enchant creature, it returns to being an enchantment creature spell, and it res', '2013-09-15'), ('e29fbc87-b6ae-5ef2-8527-0caec7a31fa6', 61610, 'If a permanent has an {X} in its mana cost, that X is 0.', '2015-06-22'), ('81bcb781-c127-5def-8c17-ffcc2f09849a', 286, 'Unless Time Stop is cast during the Ending phase, any “at the beginning of the end step”-triggered abilities don’t get the chance to trigger on the turn Time Stop is cast. These abilities will trigger at the beginning of the next end step.', '2004-12-01'), ('297e421c-b653-5a33-bf1c-b40381cd05ec', 15377, 'If the non-awaken part of the spell doesn’t require a target and you cast the spell for its awaken cost, then the spell won’t resolve if the target land you control becomes illegal before the spell resolves (such as due to being destroyed in response to t', '2015-08-25'), ('2388489c-54c5-5649-b178-d1b00e4cfc5e', 22895, 'A conspiracy doesn’t count as a card in your deck for purposes of meeting minimum deck size requirements. (In most drafts, the minimum deck size is 40 cards.)', '2016-08-23'), ('7ff2d473-fddb-5a25-8f7a-fd5fc0578404', 67029, 'Once Hour of Devastation begins to resolve, no player may take actions until it’s done. Notably, players can’t try to give a creature indestructible again to save it from the damage.', '2017-07-14'), ('c0a78a33-31dd-51c7-a204-3cacf2b33c91', 8470, 'Unearth grants haste to the creature that’s returned to the battlefield. However, neither of the “exile” abilities is granted to that creature. If that creature loses all its abilities, it will still be exiled at the beginning of the end step, and if it w', '2008-10-01'), ('f5bbbeae-e0b7-50e2-8666-197c3831aa8d', 29125, 'Casting a card as an Adventure isn’t casting it for an alternative cost. Effects that allow you to cast a spell for an alternative cost or without paying its mana cost may allow you to apply those to the Adventure.', '2019-10-04');
INSERT INTO `CardData` VALUES ('악귀소환술사가 정신을 어지럽힌 신령은 쉴새 없이 분노하는 심령으로 변한다.', 412235, 'c194d6c3-6f56-5753-92cb-2f69d92b57cc', '순간마법', replace('번개 도끼를 발동하기 위한 추가비용으로, 카드 한 장을 버리거나 {5}를 지불한다.\n생물을 목표로 정한다. 번개 도끼는 그 생물에게 피해 5점을 입힌다.','\n',char(10)), 192686, 'Korean', '번개 도끼'), ('« Un chef inspire le courage, mais ce sont les forgerons et les guérisseurs qui font vivre l''espoir. » —Thalia, cathare hérétique', 415390, '55a8a643-a924-5c96-ad1f-8fc2f2ac1f3f', 'Artefact : équipement', replace('La créature équipée gagne +0/+3 et a la vigilance.\nÉquipement {3} ({3} : Attachez à la créature ciblée que vous contrôlez. N''attachez l''équipement que lorsque vous pourriez lancer un rituel.)','\n',char(10)), 84705, 'French', 'Bouclier cathare'), ('파티의 죽음.', 477863, 'f6a4b7f1-41fb-5422-a019-036886c84dce', '생물 — 좀비 사티로스', '불협화음 피리꾼이 죽을 때, 0/1 백색 염소 생물 토큰 한 개를 만든다.', 198865, 'Korean', '불협화음 피리꾼'), ('Un sangpyre est toujours redoutable, mais si son feu est attisé par sorcellerie, il est capable de dévaster des armées entières.', 122820, 'a172c415-e2ee-56bb-ad04-664dd7910343', 'Créature : élémental et guerrier', 'Tant que le Sangpyre flamboyant est enchanté, il gagne +2/+2, a le piétinement et « {R} : Le Sangpyre flamboyant gagne +1/+0 jusqu''à la fin du tour. »', 70171, 'French', 'Sangpyre flamboyant'), ('Un potente mago ha creato il trespolo per sorvegliare un portale tra le dimensioni. Il mago è scomparso da tempo, ma i draghi sono ancora di guardia.', 168510, 'ab5cbeb2-4210-55e1-ab43-e1a33e274320', 'Incantesimo', '{5}{R}{R}: Metti in gioco una pedina creatura Drago 5/5 rossa con volare.', 165056, 'Italian', 'Trespolo del Drago'), ('「这都是那些蠢货闯的祸。」 ～提莎娜', 441664, 'c0cec6af-73e2-5677-a339-d778a13c4d70', '神器生物 ～魔像', '醒转拼合像的力量和防御力各等同于由你操控之地中名称不同者的种数。', 180270, 'Chinese Simplified', '醒转拼合像');
INSERT INTO (`uuid`, `text`, `date`, `id`) VALUES ('e62a42f9-3358-5738-8d82-334d00bc50e7', 'You choose which opponent or opposing planeswalker the token is attacking as you put it onto the battlefield. It doesn’t have to be the same player or planeswalker Flamerush Rider is attacking.', '2014-11-24', 34131);
INSERT INTO `MagicCards` (`text`, `layout`, `id`, `edhrecRank`, `colors`, `cardKingdomId`, `cardKingdomFoilId`, `multiverseId`, `manaCost`, `convertedManaCost`, `isReprint`, `isStarter`, `artist`, `hasAlternativeDeckLimit`, `availability`, `hasFoil`, `scryfallIllustrationId`, `scryfallOracleId`, `setCode`, `hasNonFoil`, `scryfallId`, `isOnlineOnly`, `isStorySpotlight`, `isFullArt`, `isAlternative`, `originalText`, `mcmMetaId`, `subtypes`, `mtgjsonV4Id`, `power`, `purchaseUrls`, `type`, `hasContentWarning`, `types`, `isReserved`, `isTextless`, `isTimeshifted`, `mtgoFoilId`, `mcmId`, `borderColor`, `frameVersion`, `isPromo`, `printings`, `keywords`, `uuid`, `toughness`, `colorIdentity`, `originalType`, `tcgplayerProductId`, `number`, `mtgoId`, `name`, `rarity`, `isOversized`) VALUES (replace('Echo {5}{R} (At the beginning of your upkeep, if this came under your control since the beginning of your last upkeep, sacrifice it unless you pay its echo cost.)\nWhen Hammerheim Deadeye enters the battlefield, destroy target creature with flying.','\n',char(10)), 'normal', 34350, 16248, 'R', '190125', '190377', '370401', '{3}{R}', 4.0, 1, 0, 'Carl Critchlow', 0, 'mtgo,paper', 1, '24ec69f1-0edf-4b4f-a89e-04ea2fd40d7f', 'a6962ccc-9883-48ca-9a5f-aeb68e66fd97', 'MMA', 1, '1bd39a59-688f-4465-8f00-540326c41128', 0, 0, 0, 0, replace('Echo {5}{R} (At the beginning of your upkeep, if this came under your control since the beginning of your last upkeep, sacrifice it unless you pay its echo cost.)\nWhen Hammerheim Deadeye enters the battlefield, destroy target creature with flying.','\n',char(10)), '8687', 'Giant,Warrior', '28e85441-745b-5f35-aab7-655a300b912c', '3', '{''cardKingdom'': ''https://mtgjson.com/links/262bb9a4bbc48852'', ''cardKingdomFoil'': ''https://mtgjson.com/links/5c7bbc6eadab02c1'', ''cardmarket'': ''https://mtgjson.com/links/4cbbfdeb43c57038'', ''tcgplayer'': ''https://mtgjson.com/links/4e53bf3f32d4c993''}', 'Creature — Giant Warrior', 0, 'Creature', 0, 0, 0, '48627', '262073', 'black', '2003', 0, 'MMA,PLC', 'Echo', 'aa923abe-e78c-528e-a35b-6bbbe9876b60', '3', 'R', 'Creature — Giant Warrior', '68381', '119', '48626', 'Hammerheim Deadeye', 'common', 0);
