INSERT INTO `MagicCardRulings` VALUES ('2015-06-22', 'Somberwald Alpha’s first ability will give each creature you control that becomes blocked +1/+1 until end of turn. It doesn’t matter how many of your opponent’s creatures are blocking each of your creatures.', 61958, '6c7ad929-2b1f-5248-ae00-e30d30209401'), ('2004-10-04', 'If the spell being copied targets a spell on the stack, it is possible to target Fork itself since Fork is still on the stack when you pick the target(s) for the copy. Note that the copy’s target will be illegal when it resolves.', 47430, 'd8df45dc-4f88-5dee-88c7-7dfa8430fbac'), ('2008-10-01', 'In a Two-Headed Giant game, a creature “attacks alone” if it’s the only creature declared as an attacker by your entire team. If you control that attacking creature, your exalted abilities will trigger but your teammate’s exalted abilities won’t.', 7730, '91ab4603-562c-59b7-8337-6c5ef922477a'), ('2018-01-19', 'Once you have the city’s blessing, you have it for the rest of the game, even if you lose control of some or all of your permanents. The city’s blessing isn’t a permanent itself and can’t be removed by any effect.', 84915, 'd1e5524f-526b-5596-963b-b5bbf0be5037');
INSERT INTO (`isNonFoilOnly`, `totalSetSize`, `id`, `name`, `isFoilOnly`, `code`, `isPartialPreview`, `keyruneCode`, `releaseDate`, `type`, `isOnlineOnly`, `baseSetSize`, `isForeignOnly`) VALUES (0, 2, 364, 'Love Your LGS', 1, 'PLGS', 0, 'PMEI', '2020-05-18', 'promo', 0, 2, 0);
INSERT INTO `CardData` (`type`, `multiverseid`, `id`, `flavorText`, `uuid`, `language`, `name`, `text`) VALUES ('Criatura — Hidra', 404968, 34369, '', 'be4a442c-5ce0-52f6-8a97-ffc70d7bef7d', 'Spanish', 'Hidra de Oran-Rief', 'Arrolla.Aterrizaje — Siempre que una tierra entre al campo de batalla bajo tu control, pon un contador +1/+1 sobre la Hidra de Oran-Rief. Si esa tierra es un bosque, en vez de eso, pon dos contadores +1/+1 sobre la Hidra de Oran-Rief.'), ('Criatura — Chamán orco', 389289, 118061, '"Ningún cuerpo puede contener tanta furia. Me recuerda a otra batalla, de mucho tiempo atrás". —Sarkhan Vol', 'eb0c06a5-5887-5b6c-855c-79fda9301419', 'Spanish', 'Aullador bélico mardu', 'Incursión — Cuando el Aullador bélico mardu entre al campo de batalla, si atacaste con una criatura este turno, agrega {R}{W}{B} a tu reserva de maná.'), ('结界～灵气', 383616, 133779, '', 'f02671a6-fcd4-5384-83d2-6cde763f9e10', 'Chinese Simplified', '压迫射线', replace('结附于生物\n除非所结附之生物的操控者支付{3}，否则它不能进行攻击或阻挡。\n所结附之生物的起动式异能增加{3}来起动。','\n',char(10))), ('Criatura — Asesino humano aliado', 404898, 33949, '"Es difícil encontrar sus puntos débiles, pero disfruto mucho buscándolos".', '83f1ff24-22b0-586a-81fa-d7baa6cebd87', 'Spanish', 'Tiradora de primera de Hagra', '{4}{B}: La criatura objetivo obtiene -1/-1 hasta el final del turno.'), ('生物 ～人類／斥候', 482328, 105689, '考慮到有狂熱軍隊、卑劣獵者和龐巨怪獸，留點心思提防天邊總是好的。', '86cf4d49-4698-576b-ae97-e16fceeee184', 'Chinese Traditional', '警覺智絆人', replace('警戒\n在你的結束步驟開始時，你每操控一個具警戒異能的生物，便獲得1點生命。','\n',char(10))), ('インスタント', 499405, 58327, '熱意は準備にしかず。', 'ad5c9ed1-51b1-5f48-a4d4-47e4a92b5247', 'Japanese', 'マナ吸収', '呪文１つを対象とする。それを打ち消す。あなたの次のメイン・フェイズの開始時に、その呪文の点数で見たマナ・コストに等しい点数の{C}を加える。');
