INSERT INTO (`uuid`, `id`, `date`, `text`) VALUES ('8a601624-9e4a-55b4-9559-29c4b8162a44', 18500, '2009-10-01', 'Gabriel Angelfire will have the ability it gains through your next untap step, but will no longer have it during your next upkeep step.');
INSERT INTO `MagicRulings` (`text`, `date`, `id`, `uuid`) VALUES ('If there are additional costs to cast an instant or sorcery spell, apply those before applying cost reductions.', '2015-06-22', 61650, 'a20dcbbe-28bc-5983-bb71-10b7407b39bb');
INSERT INTO `Rulings` (`date`, `text`, `uuid`, `id`) VALUES ('2013-04-15', 'You may pay {W/B} a maximum of one time for each extort triggered ability. You decide whether to pay when the ability resolves.', '9a01e6be-e956-5754-bf04-adc1b23da9f5', 14441), ('2011-06-01', 'Although creature tokens go to the graveyard before ceasing to exist, they never count as creature cards and won’t increase the bonus granted by Bonehoard, however briefly.', '828e071b-ca89-51d9-8fde-9b02e5878f10', 71144), ('2017-07-14', 'Once you’ve activated an embalm ability, the card is immediately exiled. Opponents can’t try to stop the ability by exiling the card with an effect such as that of Crook of Condemnatnion.', 'bfdbca72-a1fd-5686-af3f-b6bd154fe856', 70441), ('2019-10-04', 'An adventurer card is a creature card in every zone except the stack, as well as while on the stack if not cast as an Adventure. Ignore its alternative characteristics in those cases. For example, while it’s in your graveyard, Giant Killer is a white crea', '21710295-d437-5b12-a1b0-56094ecc1b58', 65625), ('2010-06-15', 'Rebound will have no effect on copies of spells because you don’t cast them from your hand.', '826cbf1f-0bc2-5fbd-922e-d0af8f9f5687', 85652), ('2014-09-20', 'Kheru Lich Lord grants flying, trample, and haste to the creature that’s returned to the battlefield. However, neither of the “exile” abilities is granted to that creature. If that creature loses all its abilities, it will still be exiled at the beginning', 'cd110822-4eb9-52a3-a959-9e7ff0c9a8f5', 46738), ('2009-10-01', 'A plane card is treated as if its text box included “When you roll {PW}, put this card on the bottom of its owner’s planar deck face down, then move the top card of your planar deck off that planar deck and turn it face up.” This is called the “planeswalk', '202e6df5-33d8-5706-afcf-1db90ae22137', 61145), ('2009-05-01', 'You gain 4 life whether or not the targeted spell’s controller pays {4} and whether or not the targeted spell is countered.', '937ea00a-f4ab-5bd6-8bda-750fc653ff1b', 8136);
INSERT INTO (`convertedManaCost`, `hasContentWarning`, `originalType`, `colors`, `hasNonFoil`, `hasFoil`, `isReprint`, `manaCost`, `artist`, `name`, `isAlternative`, `cardKingdomId`, `rarity`, `number`, `colorIdentity`, `printings`, `setCode`, `uuid`, `borderColor`, `edhrecRank`, `toughness`, `frameVersion`, `mcmId`, `tcgplayerProductId`, `isReserved`, `originalText`, `isTimeshifted`, `isOnlineOnly`, `availability`, `isStorySpotlight`, `keywords`, `scryfallOracleId`, `isFullArt`, `mtgjsonV4Id`, `hasAlternativeDeckLimit`, `flavorText`, `isTextless`, `scryfallId`, `types`, `text`, `isStarter`, `scryfallIllustrationId`, `isOversized`, `purchaseUrls`, `id`, `mcmMetaId`, `layout`, `subtypes`, `multiverseId`, `power`, `type`, `isPromo`) VALUES (4.0, 0, 'Summon - Specter', 'B', 1, 0, 0, '{2}{B}{B}', 'Ruth Thompson', 'Abyssal Specter', 0, '20000', 'uncommon', '113', 'B', '5ED,6ED,7ED,8ED,BRB,DDC,DKM,DPA,DVD,ICE,MM3,PS11', 'ICE', '2cf7a942-363c-5b65-bad8-9bcfe73dce28', 'black', 8296, '3', '1993', '6213', '4575', 0, replace('Flying\nWhenever Abyssal Specter damages any player, that player chooses and discards a card from his or her hand. Ignore this ability if the player has no cards in hand.','\n',char(10)), 0, 0, 'paper', 0, 'Flying', '51833cff-6519-4806-8d91-0040e9a02189', 0, '9615e749-ed22-5544-b03b-cd159cf9be6e', 0, replace('"Open the gates, and bid them enter."\n—Lim-Dûl, the Necromancer','\n',char(10)), 0, 'fc26f19c-bcf7-4bd8-af42-4757dbe47fb1', 'Creature', replace('Flying\nWhenever Abyssal Specter deals damage to a player, that player discards a card.','\n',char(10)), 0, '766df90e-d820-475c-a561-a42c43b6727b', 0, '{''cardKingdom'': ''https://mtgjson.com/links/bf85687083bf958a'', ''cardmarket'': ''https://mtgjson.com/links/6ba7eef345ff1adc'', ''tcgplayer'': ''https://mtgjson.com/links/b8abfb742cf2c9c2''}', 22361, '24', 'normal', 'Specter', '2437', '2', 'Creature — Specter', 0);
